args.CommandLine:
Get-ChildItem -Path "C:\Users\RONALDO\.gemini\antigravity\brain" -Directory | ForEach-Object {
    $t = Join-Path $_.FullName ".system_generated\logs\transcript.jsonl"
    if (Test-Path $t) {
        $first = Get-Content $t -TotalCount 5 | Out-String
        $lines = (Get-Content $t).Count
        [PSCustomObject]@{
            Id = $_.Name
            LastWrite = $_.LastWriteTime
            Lines = $lines
            IsExamen2 = ($first -match "Examen2|citamedicaclinicavidasalud")
        }
    }
} | Format-Table -AutoSize

